#vitaflow-native {
            --page-bg: #f6f5f7;
            --surface: #fff;
            --surface-muted: #faf8fb;
            --text: #302b36;
            --muted: #756c7c;
            --accent: #80548d;
            --border: #e7e1eb;
            --card-shadow: 0 5px 18px rgba(63, 42, 78, 0.07);
        }
#vitaflow-native * { margin: 0; padding: 0; box-sizing: border-box; }
#vitaflow-native {
            background: var(--page-bg);
            font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
            color: var(--text);
            padding: 32px 24px 64px;
            min-height: 100vh;
        }
#vitaflow-native .ripple-card, #vitaflow-native button, #vitaflow-native .account-card, #vitaflow-native .goal-card, #vitaflow-native .cal-day, #vitaflow-native .stat-card, #vitaflow-native .record-btn, #vitaflow-native .tab-btn { transition: border-color 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease; cursor: pointer; }
#vitaflow-native .ripple-card:hover, #vitaflow-native .account-card:hover, #vitaflow-native .goal-card:hover, #vitaflow-native .cal-day:hover, #vitaflow-native .stat-card:hover { border-color: var(--accent); box-shadow: var(--card-shadow); }
#vitaflow-native button:active { filter: brightness(0.96); }
#vitaflow-native .container, #vitaflow-native .detail-page { max-width: 1280px; margin: 0 auto; }
#vitaflow-native .user-profile { background: var(--surface); border-radius: 18px; padding: 0 22px; margin-bottom: 30px; border: 1px solid var(--border); }
#vitaflow-native .user-name { font-size: 1.7rem; font-weight: 700; background: linear-gradient(135deg, #c4679c, #8b5e9e); -webkit-background-clip: text; background-clip: text; color: transparent; margin-bottom: 10px; }
#vitaflow-native .user-intro { font-size: 0.95rem; color: #6d4b6e; line-height: 1.8; margin-top: 10px; }
#vitaflow-native .tags { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 16px; }
#vitaflow-native .tag { background: linear-gradient(135deg, #f0e0ff, #ffe0f0); padding: 6px 16px; border-radius: 24px; font-size: 0.85rem; color: #8b5e9e; border: 1px solid rgba(200, 160, 200, 0.4); }
#vitaflow-native .accounts-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; margin-bottom: 28px; }
#vitaflow-native .account-card { background: var(--surface); border-radius: 20px; padding: 22px 18px; border: 1px solid var(--border); }
#vitaflow-native .account-icon { font-size: 1.8rem; margin-bottom: 10px; }
#vitaflow-native .account-title { font-weight: 700; font-size: 1.25rem; margin-bottom: 8px; color: #4a2c3a; }
#vitaflow-native .account-score { font-size: 2rem; font-weight: 800; background: linear-gradient(135deg, #c4679c, #8b5e9e); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .trend-badge { font-size: 0.75rem; background: rgba(200, 160, 200, 0.25); border-radius: 20px; padding: 4px 12px; display: inline-block; margin-top: 10px; color: #8b5e9e; }
#vitaflow-native .row-split { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 24px; margin-bottom: 28px; }
#vitaflow-native .calendar-panel, #vitaflow-native .todo-panel { background: var(--surface); border-radius: 22px; padding: 24px; backdrop-filter: blur(10px); border: 1px solid rgba(200, 160, 200, 0.3); }
#vitaflow-native .panel-title { font-size: 1.2rem; font-weight: 700; color: #5a3a4a; margin-bottom: 16px; display: flex; align-items: center; gap: 10px; }
#vitaflow-native .month-nav { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
#vitaflow-native .month-btn { background: rgba(200, 160, 200, 0.2); border: none; border-radius: 20px; padding: 8px 16px; font-size: 0.9rem; color: #5a3a4a; }
#vitaflow-native .current-month { font-size: 1.1rem; font-weight: 600; color: #6a4a5a; }
#vitaflow-native .weekdays { display: grid; grid-template-columns: repeat(7, 1fr); text-align: center; font-weight: 600; margin: 12px 0 10px; color: #9a7a8a; }
#vitaflow-native .calendar-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 8px; }
#vitaflow-native .cal-day { background: var(--surface-muted); border-radius: 12px; padding: 12px 8px; text-align: center; font-size: 0.9rem; font-weight: 500; border: 1px solid var(--border); position: relative; }
#vitaflow-native .cal-day.selected { background: linear-gradient(135deg, #f0e0ff, #ffe0f0); border-color: #bc8fcf; color: #4a2c3a; font-weight: 600; }
#vitaflow-native .happy-marker { font-size: 0.8rem; margin-top: 4px; }
#vitaflow-native .todo-input-area { margin-bottom: 16px; }
#vitaflow-native .account-add-btns { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }
#vitaflow-native .account-add-btn { padding: 8px 16px; border-radius: 20px; border: 1px solid #e0c0e0; background: rgba(255, 245, 252, 0.9); font-size: 0.85rem; font-weight: 500; color: #6a4a5a; }
#vitaflow-native .account-add-btn.active { background: linear-gradient(135deg, #f0e0ff, #ffe0f0); border-color: #bc8fcf; }
#vitaflow-native .todo-input-group { display: flex; gap: 10px; }
#vitaflow-native .todo-input-group input { flex: 1; background: rgba(255, 245, 252, 0.9); border: 1px solid rgba(200, 160, 200, 0.35); border-radius: 50px; padding: 12px 18px; color: #3a2a47; outline: none; font-size: 0.95rem; }
#vitaflow-native .todo-input-group input::placeholder { color: #aa9a9a; }
#vitaflow-native .happy-select { background: rgba(255, 245, 252, 0.9); border: 1px solid rgba(200, 160, 200, 0.35); border-radius: 50px; padding: 12px 14px; color: #6a4a5a; font-size: 0.9rem; }
#vitaflow-native .add-btn { background: linear-gradient(135deg, #c4679c, #8b5e9e); color: white; border: none; border-radius: 50px; padding: 12px 24px; font-weight: 600; cursor: pointer; font-size: 0.9rem; }
#vitaflow-native .todo-list { max-height: 320px; overflow-y: auto; }
#vitaflow-native .todo-item { background: var(--surface); border-radius: 14px; padding: 12px 18px; margin-bottom: 10px; display: flex; justify-content: space-between; align-items: center; border: 1px solid var(--border); }
#vitaflow-native .todo-left { display: flex; align-items: center; gap: 12px; flex: 1; }
#vitaflow-native .todo-check { width: 20px; height: 20px; accent-color: #c4679c; cursor: pointer; }
#vitaflow-native .todo-text { flex: 1; color: #4a3a4a; font-size: 0.95rem; }
#vitaflow-native .todo-text.completed { text-decoration: line-through; color: #aa9a9a; }
#vitaflow-native .todo-account { background: linear-gradient(135deg, #ffe0f0, #f0e0ff); border-radius: 20px; padding: 4px 10px; font-size: 0.75rem; color: #8b5e9e; margin-right: 8px; }
#vitaflow-native .todo-happy { font-size: 1.1rem; margin-right: 8px; }
#vitaflow-native .delete-btn { background: none; border: none; color: #c4679c; cursor: pointer; font-size: 1rem; padding: 4px; }
#vitaflow-native .stats-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
#vitaflow-native .stat-card { background: var(--surface); border-radius: 20px; padding: 24px 18px; border: 1px solid var(--border); text-align: center; }
#vitaflow-native .stat-value { font-size: 2.2rem; font-weight: 800; background: linear-gradient(135deg, #c4679c, #8b5e9e); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .stat-label { font-size: 0.95rem; color: #8b5e9e; margin-top: 8px; }
#vitaflow-native .chart-container { position: relative; height: 200px; margin-top: 16px; }
#vitaflow-native .goal-section { margin-top: 28px; }
#vitaflow-native .goal-input-area { display: flex; gap: 12px; margin-bottom: 20px; }
#vitaflow-native .goal-input-area input { flex: 1; background: rgba(255, 245, 252, 0.9); border: 1px solid rgba(200, 160, 200, 0.35); border-radius: 50px; padding: 14px 20px; color: #3a2a47; outline: none; font-size: 1rem; }
#vitaflow-native .goal-suggestions { background: linear-gradient(135deg, #fff5f8, #f8f0ff); border-radius: 24px; padding: 24px; margin-top: 20px; border: 1px solid rgba(200, 160, 200, 0.3); }
#vitaflow-native .suggestion-item { padding: 14px 0; border-bottom: 1px solid rgba(200, 160, 200, 0.2); }
#vitaflow-native .suggestion-item:last-child { border-bottom: none; }
#vitaflow-native .suggestion-title { font-weight: 600; color: #6a4a5a; margin-bottom: 8px; display: flex; align-items: center; gap: 8px; }
#vitaflow-native .suggestion-text { color: #8b7a7a; font-size: 0.95rem; line-height: 1.7; }
#vitaflow-native .detail-page { display: none; }
#vitaflow-native .detail-page.active { display: block; animation: vf-native-fadeIn 0.3s ease; }
@keyframes vf-native-fadeIn {from { opacity: 0; transform: translateY(10px); }
to { opacity: 1; transform: translateY(0); }
 }
#vitaflow-native .back-btn { background: rgba(255, 250, 252, 0.9); border: 1px solid var(--border); border-radius: 24px; padding: 10px 20px; font-weight: 600; cursor: pointer; color: #6a4a5a; margin-bottom: 20px; font-size: 0.95rem; display: flex; align-items: center; gap: 8px; }
#vitaflow-native .detail-header { background: var(--surface); border-radius: 22px; padding: 28px; border: 1px solid rgba(200, 160, 200, 0.3); margin-bottom: 24px; text-align: center; }
#vitaflow-native .detail-icon { font-size: 4rem; margin-bottom: 12px; }
#vitaflow-native .detail-title { font-size: 1.8rem; font-weight: 700; margin-bottom: 16px; }
#vitaflow-native .physical-theme { background: linear-gradient(135deg, #e88a4c, #d470a0); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .emotional-theme { background: linear-gradient(135deg, #c4679c, #9c5a8e); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .focus-theme { background: linear-gradient(135deg, #8b5e9e, #6a4a7a); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .meaning-theme { background: linear-gradient(135deg, #a78bfa, #8b6bda); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .streak-theme { background: linear-gradient(135deg, #ffb347, #ff6b9d); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .tasks-theme { background: linear-gradient(135deg, #74ebd5, #9face6); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .avg-theme { background: linear-gradient(135deg, #667eea, #764ba2); -webkit-background-clip: text; background-clip: text; color: transparent; }
#vitaflow-native .progress-ring { width: 140px; height: 140px; margin: 0 auto 16px; position: relative; }
#vitaflow-native .progress-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }
#vitaflow-native .progress-ring circle { fill: none; stroke-width: 10; stroke-linecap: round; }
#vitaflow-native .progress-ring .bg { stroke: rgba(200, 160, 200, 0.2); }
#vitaflow-native .progress-ring .fg { transition: stroke-dashoffset 0.8s ease; }
#vitaflow-native .progress-ring .center { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); text-align: center; }
#vitaflow-native .progress-ring .number { font-size: 2.2rem; font-weight: 800; }
#vitaflow-native .progress-ring .label { font-size: 0.85rem; color: #8b7a7a; }
#vitaflow-native .tabs { display: flex; gap: 12px; margin-bottom: 24px; flex-wrap: wrap; }
#vitaflow-native .tab-btn { padding: 10px 20px; border-radius: 24px; background: rgba(255, 250, 252, 0.9); border: 1px solid var(--border); font-weight: 600; color: #7a5a6a; font-size: 0.9rem; }
#vitaflow-native .tab-btn.active { background: linear-gradient(135deg, #f0e0ff, #ffe0f0); border-color: #bc8fcf; color: #5a3a4a; }
#vitaflow-native .tab-content { display: none; }
#vitaflow-native .tab-content.active { display: block; }
#vitaflow-native .theory-card { background: linear-gradient(135deg, #fff5f8, #f8f0ff); border-radius: 24px; padding: 24px; border: 1px solid rgba(200, 160, 200, 0.3); margin-bottom: 20px; }
#vitaflow-native .theory-title { font-size: 1.1rem; font-weight: 700; color: #6a4a5a; margin-bottom: 12px; display: flex; align-items: center; gap: 10px; }
#vitaflow-native .theory-text { color: #7a6a6a; line-height: 1.8; font-size: 0.95rem; }
#vitaflow-native .record-form { background: rgba(255, 250, 252, 0.95); border-radius: 24px; padding: 24px; border: 1px solid rgba(200, 160, 200, 0.3); margin-bottom: 20px; }
#vitaflow-native .form-group { margin-bottom: 18px; }
#vitaflow-native .form-label { display: block; font-weight: 600; color: #6a4a5a; margin-bottom: 10px; }
#vitaflow-native .form-input, #vitaflow-native .form-select { width: 100%; background: rgba(255, 245, 252, 0.95); border: 1px solid rgba(200, 160, 200, 0.35); border-radius: 16px; padding: 12px 16px; color: #3a2a47; outline: none; font-size: 1rem; }
#vitaflow-native .form-range { width: 100%; accent-color: #c4679c; }
